import{_ as e,o as n,c as o,a2 as i}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/en/find-match-mode.png",s="/relio/shots/en/find-hover-highlight.png",u=JSON.parse('{"title":"Find and highlight","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/find.md","filePath":"en/features/find.md"}'),r={name:"en/features/find.md"};function d(h,t,l,c,g,b){return n(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="find-and-highlight" tabindex="-1">Find and highlight <a class="header-anchor" href="#find-and-highlight" aria-label="Permalink to &quot;Find and highlight&quot;">​</a></h1><p>The find bar and match modes, Hangul initial-consonant search, hover and selection connection highlights, and highlight settings.</p><p>A short how-to is in <a href="/relio/en/quick/navigate#find-and-highlight">Getting around the canvas › Find and highlight</a> in Quick start.</p><h2 id="find-bar" tabindex="-1">Find bar <a class="header-anchor" href="#find-bar" aria-label="Permalink to &quot;Find bar&quot;">​</a></h2><p>Press <kbd>Ctrl</kbd>+<kbd>F</kbd> (Edit › Find) to open the find bar over the canvas.</p><ul><li>It searches table, column, relationship and note names (physical and logical) as you type. Every match is highlighted and everything else is dimmed.</li><li><strong>Hangul initial consonants</strong> also match, which helps with Korean names: typing <code>ㅅㅇㅈ</code> finds &quot;사용자&quot; (user).</li><li>Turn on the bar&#39;s description option (&quot;Also search table and column descriptions&quot;) to search description text too.</li><li>The bar shows the current result number and the total, like &quot;3 / 12&quot;, or &quot;No results&quot; when nothing matches. The <strong>Table</strong> · <strong>Column</strong> · <strong>Other</strong> buttons on the bar turn each kind of target on or off.</li><li>The <strong>…</strong> button at the right of the bar (Find and replace…, <kbd>Ctrl</kbd>+<kbd>H</kbd>) opens the <a href="/relio/en/features/edit#find-and-replace-dialog">find and replace dialog</a>.</li><li>Closing the bar with <kbd>Esc</kbd> or <strong>Close</strong> clears the highlights.</li></ul><h3 id="moving-between-results" tabindex="-1">Moving between results <a class="header-anchor" href="#moving-between-results" aria-label="Permalink to &quot;Moving between results&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><kbd>Enter</kbd> · <kbd>F3</kbd></td><td>Goes to the next result and flashes it once.</td></tr><tr><td><kbd>Shift</kbd>+<kbd>Enter</kbd> · <kbd>Shift</kbd>+<kbd>F3</kbd></td><td>Goes to the previous result.</td></tr><tr><td><kbd>Alt</kbd>+<kbd>W</kbd></td><td>Changes the match mode.</td></tr><tr><td><kbd>Esc</kbd></td><td>Closes the bar.</td></tr></tbody></table><p>Going past the last result shows &quot;Wrapped to the first result&quot;. An <kbd>Enter</kbd> pressed while composing Korean text only confirms the character; it does not move to another result.</p><h3 id="match-mode" tabindex="-1">Match mode <a class="header-anchor" href="#match-mode" aria-label="Permalink to &quot;Match mode&quot;">​</a></h3><p>Each click on the mode button on the bar (or <kbd>Alt</kbd>+<kbd>W</kbd>) switches the mode, and the chosen mode is remembered.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Matches when</th><th>Example: searching for <code>ID</code></th></tr></thead><tbody><tr><td>Contains (default)</td><td>It appears anywhere in the name</td><td>Both <code>MEMBER_ID</code> and <code>VALID</code></td></tr><tr><td>Word</td><td>A piece split at <code>_</code>, spaces, symbols or a case change is the same</td><td><code>MEMBER_ID</code> and <code>memberId</code> match; <code>VALID</code> does not</td></tr><tr><td>Exact</td><td>The whole name is the same</td><td>Only <code>ID</code></td></tr></tbody></table><p>Word and Exact do not use initial-consonant search.</p><figure class="shot" data-scene="find-match-mode"><img src="'+a+'" alt="Find bar — searching for ID with the match mode set to Word" loading="lazy"><figcaption>Find bar — searching for ID with the match mode set to Word</figcaption></figure><h3 id="finding-in-a-category-view" tabindex="-1">Finding in a category view <a class="header-anchor" href="#finding-in-a-category-view" aria-label="Permalink to &quot;Finding in a category view&quot;">​</a></h3><p>In a category tab, only results within that scope are highlighted. If there are matches outside it, &quot;Outside this category: n&quot; appears, and <strong>Show in all categories</strong> searches again in the &quot;All&quot; tab. Matches on things that are not drawn on the canvas, such as categories hidden from the tabs, are counted too. <a href="/relio/en/features/categories">Categories</a></p><h2 id="connection-highlight" tabindex="-1">Connection highlight <a class="header-anchor" href="#connection-highlight" aria-label="Permalink to &quot;Connection highlight&quot;">​</a></h2><ul><li><strong>Hover</strong> — Hover over a table, relationship line or column, and the connected lines and tables, and the matching primary key (PK) and foreign key (FK) columns, become slightly stronger. The rest stays as it is.</li><li><strong>Selection</strong> — Click to select, and only the connected objects stay sharp while the rest is dimmed. Selecting a category area shows only its selection border.</li><li><strong>Tooltips</strong> — Rest the mouse on a table or column to see its type, NOT NULL, FK target and description.</li><li>Clicking an item in the problem list goes to that object and highlights it briefly.</li></ul><p>Highlights exist only on screen; they never appear in image or HTML exports or in print.</p><figure class="shot" data-scene="find-hover-highlight"><img src="'+s+'" alt="Hovering over a table makes the connected relationship lines, tables and FK columns stronger" loading="lazy"><figcaption>Hovering over a table makes the connected relationship lines, tables and FK columns stronger</figcaption></figure><h2 id="highlight-settings" tabindex="-1">Highlight settings <a class="header-anchor" href="#highlight-settings" aria-label="Permalink to &quot;Highlight settings&quot;">​</a></h2><p>Change them in Tools › Settings › General › <strong>Highlight</strong>. Changes apply immediately; check them with <strong>Highlight preview</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Values</th></tr></thead><tbody><tr><td>Highlight connections on hover</td><td>On · Off</td></tr><tr><td>Highlight connections of selection</td><td>On · Off</td></tr><tr><td>Dim the rest</td><td>On · Off separately for <strong>When finding</strong> and <strong>On selection</strong></td></tr><tr><td>Dim level</td><td>Light · Medium · Strong</td></tr><tr><td>Highlight effect</td><td>Blink · Shrink slowly · Fixed, plus <strong>Times</strong> and <strong>Duration of one blink</strong></td></tr><tr><td>Reduce motion</td><td><strong>Follow system setting</strong> by default. When on, nothing blinks and only a thick border is shown.</td></tr></tbody></table><p>The highlight effect moves only for the current find result and the object you clicked in a list, and motion always ends within 3 seconds.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>If the screen dimming all the time bothers you, turn off only <strong>On selection</strong> under &quot;Dim the rest&quot;. Dimming while finding stays, so results are still easy to spot in a big model.</p></div>',25)])])}const p=e(r,[["render",d]]);export{u as __pageData,p as default};
